<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1120;
      --panel: rgba(15, 23, 42, 0.92);
      --panel-border: rgba(148, 163, 184, 0.18);
      --text: #e5eefb;
      --muted: #9fb0c9;
      --accent: #60a5fa;
      --accent-strong: #3b82f6;
      --input-bg: rgba(15, 23, 42, 0.7);
      --error: #fda4af;
      --shadow: 0 24px 60px rgba(2, 6, 23, 0.45);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 32px 16px;
      font-family: Arial, Helvetica, sans-serif;
      background:
        radial-gradient(circle at top, rgba(59, 130, 246, 0.18), transparent 32%),
        linear-gradient(180deg, #020617 0%, #0f172a 100%);
      color: var(--text);
    }

    .support-shell {
      width: min(100%, 560px);
      padding: 32px;
      border: 1px solid var(--panel-border);
      border-radius: 24px;
      background: var(--panel);
      backdrop-filter: blur(18px);
      box-shadow: var(--shadow);
    }

    .eyebrow {
      margin: 0 0 8px;
      font-size: 0.8rem;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--accent);
    }

    h1 {
      margin: 0 0 12px;
      font-size: clamp(1.9rem, 3vw, 2.4rem);
      line-height: 1.1;
    }

    .intro {
      margin: 0 0 28px;
      color: var(--muted);
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 18px;
    }

    .form-field {
      display: grid;
      gap: 8px;
    }

    label {
      font-size: 0.95rem;
      font-weight: 700;
    }

    input {
      width: 100%;
      padding: 14px 16px;
      border: 1px solid rgba(148, 163, 184, 0.22);
      border-radius: 14px;
      background: var(--input-bg);
      color: var(--text);
      font-size: 1rem;
      transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
    }

    input::placeholder {
      color: #6b7a90;
    }

    input:focus {
      outline: none;
      border-color: rgba(96, 165, 250, 0.85);
      box-shadow: 0 0 0 4px rgba(96, 165, 250, 0.16);
      transform: translateY(-1px);
    }

    .helper-text,
    .error-message,
    .status-message {
      font-size: 0.9rem;
      line-height: 1.45;
    }

    .helper-text {
      color: var(--muted);
    }

    .error-message {
      display: none;
      color: var(--error);
    }

    .form-field.invalid input {
      border-color: rgba(251, 113, 133, 0.9);
      box-shadow: 0 0 0 4px rgba(251, 113, 133, 0.12);
    }

    .form-field.invalid .error-message {
      display: block;
    }

    button {
      margin-top: 8px;
      padding: 14px 18px;
      border: 0;
      border-radius: 14px;
      background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
      color: #eff6ff;
      font-size: 1rem;
      font-weight: 700;
      cursor: pointer;
      transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
      box-shadow: 0 16px 32px rgba(37, 99, 235, 0.28);
    }

    button:hover {
      filter: brightness(1.05);
      transform: translateY(-1px);
    }

    button:focus-visible {
      outline: 3px solid rgba(191, 219, 254, 0.6);
      outline-offset: 3px;
    }

    .status-message {
      min-height: 1.4em;
      margin: 0;
      color: #93c5fd;
    }

    @media (max-width: 640px) {
      .support-shell {
        padding: 24px;
        border-radius: 20px;
      }
    }
  </style>
</head>
<body>
  <section class="support-shell" aria-labelledby="support-form-title">
    <p class="eyebrow">Support</p>
    <h1 id="support-form-title">Contact our support team</h1>
    <p class="intro">Share your details and we’ll reach out to help with your request as soon as possible.</p>

    <form id="support-form" novalidate>
      <div class="form-field">
        <label for="full-name">Full name</label>
        <input id="full-name" name="fullName" type="text" autocomplete="name" placeholder="Jane Doe" required>
        <p class="error-message" aria-live="polite">Please enter your full name.</p>
      </div>

      <div class="form-field">
        <label for="email-address">Email address</label>
        <input id="email-address" name="email" type="email" autocomplete="email" placeholder="jane@example.com" required>
        <p class="error-message" aria-live="polite">Please enter a valid email address.</p>
      </div>

      <div class="form-field">
        <label for="phone-number">Phone number</label>
        <input id="phone-number" name="phone" type="tel" autocomplete="tel" inputmode="tel" placeholder="+1 555 123 4567">
        <p class="helper-text">Optional. Use digits with spaces, dashes, or parentheses, for example: +1 555 123 4567.</p>
        <p class="error-message" aria-live="polite">Please use a valid phone number format.</p>
      </div>

      <button type="submit">Submit</button>
      <p class="status-message" id="form-status" aria-live="polite"></p>
    </form>
  </section>

  <script>
    const form = document.getElementById("support-form");
    const statusMessage = document.getElementById("form-status");
    const fields = Array.from(form.querySelectorAll(".form-field"));
    const phonePattern = /^[+]?[0-9()\s-]{7,20}$/;

    function getInput(field) {
      return field.querySelector("input");
    }

    function getValidationMessage(input) {
      const value = input.value.trim();

      if (input.name === "fullName" && !value) {
        return "Please enter your full name.";
      }

      if (input.name === "email") {
        if (!value) {
          return "Please enter your email address.";
        }

        if (!input.checkValidity()) {
          return "Please enter a valid email address.";
        }
      }

      if (input.name === "phone" && value && !phonePattern.test(value)) {
        return "Please use a valid phone number format.";
      }

      return "";
    }

    function setFieldState(field, message) {
      const input = getInput(field);
      const error = field.querySelector(".error-message");
      const isInvalid = Boolean(message);

      field.classList.toggle("invalid", isInvalid);
      input.setAttribute("aria-invalid", String(isInvalid));
      error.textContent = message || "";
    }

    function validateField(field) {
      const input = getInput(field);
      const message = getValidationMessage(input);
      setFieldState(field, message);
      return !message;
    }

    fields.forEach((field) => {
      const input = getInput(field);

      input.addEventListener("blur", () => {
        validateField(field);
      });

      input.addEventListener("input", () => {
        if (field.classList.contains("invalid")) {
          validateField(field);
        }
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const isFormValid = fields.every((field) => validateField(field));

      if (!isFormValid) {
        statusMessage.textContent = "Please correct the highlighted fields before submitting.";
        return;
      }

      statusMessage.textContent = "Thanks! Your support request is ready to send.";
      form.reset();
      fields.forEach((field) => setFieldState(field, ""));
    });
  </script>
</body>
</html>
